function snap(v, grid = GRID) {
  return Math.round(v / grid) * grid;
}
function placeLabel(t2, rot, dx, dy) {
  const r = ((rot ?? 0) % 360 + 360) % 360;
  let lx = dx, ly = dy;
  if (r === 90) {
    lx = dy;
    ly = -dx;
  } else if (r === 180) {
    lx = -dx;
    ly = -dy;
  } else if (r === 270) {
    lx = -dy;
    ly = dx;
  }
  t2.setAttribute("x", String(lx));
  t2.setAttribute("y", String(ly));
  if (r) t2.setAttribute("transform", `rotate(${-r} ${lx} ${ly})`);
}

