      svg2("line", { x1: SCR.x, y1: SCR.y + i * DIV_H, x2: SCR.x + SCR.w, y2: SCR.y + i * DIV_H, stroke: i === 4 ? "#2c5233" : "#1c3320", "stroke-width": i === 4 ? 1.5 : 0.7 }, g);
