    const ch2Line = svg2("polyline", { fill: "none", stroke: C2, "stroke-width": 1.7, "pointer-events": "none" }, g);
    const trgLine = svg2("line", { x1: SCR.x, x2: SCR.x + SCR.w, stroke: TRG, "stroke-dasharray": "5,4", "stroke-width": 1.2, "pointer-events": "none" }, g);
    const curA = svg2("line", { y1: SCR.y, y2: SCR.y + GRID_H, stroke: "#ffffff", "stroke-dasharray": "2,3", "stroke-width": 1, "pointer-events": "none", visibility: "hidden" }, g);
    const curB = svg2("line", { y1: SCR.y, y2: SCR.y + GRID_H, stroke: "#ffffff", "stroke-dasharray": "2,3", "stroke-width": 1, "pointer-events": "none", visibility: "hidden" }, g);
