  mask.appendChild(box);
  const title = document.createElement("div");
  title.style.cssText = "background:#243447;color:#fff;padding:8px 14px;font-size:14px;font-weight:bold;display:flex;justify-content:space-between;align-items:center;";
  const titleText = document.createElement("span");
  titleText.textContent = spec.title;
