  sim.stop();
  const keepCode = getMainCode();
  model.loadFromTemplate(currentTemplate.circuit, keepCode);
  model.wires = [];
  model.pinLabels.clear();
  model.forcedNets.clear();
  compiled = null;
  lastHex = null;
  $16("#btn-download").disabled = true;
  $16("#btn-savehex").disabled = true;
