  const box = document.createElement("div");
  box.style.cssText = `background:#fff;border:1px solid var(--border);border-radius:10px;max-width:${opts.wide ? 860 : 560}px;width:92vw;max-height:86vh;overflow:auto;box-shadow:0 12px 40px rgba(0,0,0,.2)`;
  box.innerHTML = `<div style="display:flex;align-items:center;padding:12px 16px;border-bottom:1px solid var(--border)"><b style="font-size:15px">${title}</b><span style="flex:1"></span><button id="mvl-modal-close" style="border:none;background:#eee;border-radius:6px;padding:4px 10px;cursor:pointer">\u2715</button></div><div style="padding:14px 16px" id="mvl-modal-body">${bodyHtml}</div>`;
  overlay.appendChild(box);
